import {
  DataTypes,
  Model,
  type CreationOptional,
  type InferAttributes,
  type InferCreationAttributes,
  type Sequelize,
} from 'sequelize';
import { dateColumn, fkColumn, idColumn, timestampColumns } from './_columns';

export type ResidentStatus = 'ACTIVE' | 'INACTIVE';
export type ResidentSource = 'ADMIN' | 'IMPORT' | 'JOIN_REQUEST' | 'HOUSEHOLD' | 'TENANCY' | 'TRANSFER';

/**
 * Module 09 section 7.1: a person in the society, with or without a login. Paranoid. `activeMobile` and `activeUserId` are
 * generated by MySQL (only non-deleted rows compete for a mobile and a login) and are not mapped here.
 */
export class Resident extends Model<InferAttributes<Resident>, InferCreationAttributes<Resident>> {
  declare id: CreationOptional<number>;
  declare societyId: number;
  declare userId: number | null;
  declare memberId: number | null;
  declare name: string;
  declare mobile: string | null;
  declare alternateMobile: string | null;
  declare email: string | null;
  declare dateOfBirth: string | null;
  declare gender: string | null;
  declare photoFileId: number | null;
  declare preferredLanguage: string;
  declare isNri: boolean;
  declare overseasPhone: string | null;
  declare localRepresentativeResidentId: number | null;
  declare status: ResidentStatus;
  declare source: ResidentSource;
  declare directoryVisible: boolean;
  declare showMobileInDirectory: boolean;
  declare showEmailInDirectory: boolean;
  declare showPhotoInDirectory: boolean;
  declare adminNote: string | null;
  declare anonymisedAt: Date | null;
  declare version: number;
  declare createdBy: number | null;
  declare updatedBy: number | null;
  declare createdAt: CreationOptional<Date>;
  declare updatedAt: CreationOptional<Date>;
  declare deletedAt: Date | null;

  static initModel(sequelize: Sequelize): void {
    Resident.init(
      {
        id: idColumn,
        societyId: fkColumn(false),
        userId: fkColumn(true),
        memberId: fkColumn(true),
        name: { type: DataTypes.STRING(120), allowNull: false },
        mobile: { type: DataTypes.CHAR(10), allowNull: true, defaultValue: null },
        alternateMobile: { type: DataTypes.CHAR(10), allowNull: true, defaultValue: null },
        email: { type: DataTypes.STRING(254), allowNull: true, defaultValue: null },
        dateOfBirth: { type: DataTypes.DATEONLY, allowNull: true, defaultValue: null },
        gender: { type: DataTypes.STRING(12), allowNull: true, defaultValue: null },
        photoFileId: fkColumn(true),
        preferredLanguage: { type: DataTypes.STRING(10), allowNull: false, defaultValue: 'en-IN' },
        isNri: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: false },
        overseasPhone: { type: DataTypes.STRING(16), allowNull: true, defaultValue: null },
        localRepresentativeResidentId: fkColumn(true),
        status: { type: DataTypes.STRING(10), allowNull: false, defaultValue: 'ACTIVE' },
        source: { type: DataTypes.STRING(20), allowNull: false, defaultValue: 'ADMIN' },
        directoryVisible: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: true },
        showMobileInDirectory: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: false },
        showEmailInDirectory: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: false },
        showPhotoInDirectory: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: false },
        adminNote: { type: DataTypes.STRING(500), allowNull: true, defaultValue: null },
        anonymisedAt: dateColumn(),
        version: { type: DataTypes.INTEGER.UNSIGNED, allowNull: false, defaultValue: 1 },
        createdBy: fkColumn(true),
        updatedBy: fkColumn(true),
        ...timestampColumns,
        deletedAt: dateColumn(),
      },
      { sequelize, tableName: 'residents', paranoid: true },
    );
  }
}
